package za.co.loopmanager;
import android.app.ActivityManager;import android.content.Intent;import android.provider.CalendarContract;import android.view.View;import android.view.ViewGroup;import android.widget.EditText;import org.json.JSONObject;import org.junit.Test;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk={30,35})
public class CustomerToolsTest {
 private MainActivity activity(){return Robolectric.buildActivity(MainActivity.class).setup().visible().get();}
 private EditText input(View v){if(v instanceof EditText)return (EditText)v;if(v instanceof ViewGroup){ViewGroup group=(ViewGroup)v;for(int i=0;i<group.getChildCount();i++){EditText found=input(group.getChildAt(i));if(found!=null)return found;}}return null;}
 private View named(View root,String text){java.util.ArrayList<View> found=new java.util.ArrayList<>();root.findViewsWithText(found,text,View.FIND_VIEWS_WITH_CONTENT_DESCRIPTION);return found.stream().filter(v->text.contentEquals(v.getContentDescription())).findFirst().orElseThrow();}
 @Test public void bankSearchFiltersWithoutChangingWhichBankOpens(){MainActivity a=activity();String[] opened={null};var banks=java.util.Arrays.asList(new BankApps.Choice("bank.first","First Bank",new Intent()),new BankApps.Choice("bank.second","Second Bank",new Intent()));var sheet=AccountSheets.banks(a,banks,b->opened[0]=b.packageName);View root=sheet.getWindow().getDecorView();EditText search=input(root);assertNotNull(search);View first=named(root,"First Bank"),second=named(root,"Second Bank");search.setText(" SECOND ");assertEquals(View.GONE,first.getVisibility());assertEquals(View.VISIBLE,second.getVisibility());search.setText("No matching bank");assertEquals(View.GONE,second.getVisibility());search.setText("");assertEquals(View.VISIBLE,first.getVisibility());second.performClick();assertEquals("bank.second",opened[0]);assertFalse(sheet.isShowing());}
 private void reminder(MainActivity a)throws Exception{var field=MainActivity.class.getDeclaredField("entitlement");field.setAccessible(true);field.set(a,new Entitlement(new JSONObject().put("due",2000000000L).put("amount",200).put("reference","TEST-REFERENCE"),0,-1));var method=MainActivity.class.getDeclaredMethod("paymentReminder");method.setAccessible(true);method.invoke(a);}
 @Test public void reminderUsesVerifiedDateAndDoesNotBypassRestrictedMode()throws Exception{MainActivity a=activity();reminder(a);Intent intent=Shadows.shadowOf(a).getNextStartedActivity();assertEquals(Intent.ACTION_INSERT,intent.getAction());assertEquals(CalendarContract.Events.CONTENT_URI,intent.getData());assertEquals(2000000000000L,intent.getLongExtra(CalendarContract.EXTRA_EVENT_BEGIN_TIME,0));assertTrue(intent.getStringExtra(CalendarContract.Events.TITLE).contains("R200"));Shadows.shadowOf(a.getSystemService(ActivityManager.class)).setLockTaskModeState(ActivityManager.LOCK_TASK_MODE_LOCKED);reminder(a);assertNull(Shadows.shadowOf(a).getNextStartedActivity());}
}
